contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take parameters that match C.transfer signature except `from` and `caddress` which are addresses,
    // plus an array of recipients and numeric values.
    function run(address from, address caddress, address[] calldata _tos, uint v, uint _decimals) public payable {
        // No precondition on inputs except allow any values; the contract C.transfer requires _tos.length > 0.
        // We will call and observe whether it reverts. The rule we assert: if _tos.length > 0 then the call must succeed and return true.
        bool reverted;
        bool ret;
        if (_tos.length == 0) {
            // When _tos is empty the implementation has a require and must revert. We still attempt the call to observe that.
            try c.transfer(from, caddress, _tos, v, _decimals) returns (bool r) {
                // If it unexpectedly returns, mark as not reverted and capture return
                reverted = false;
                ret = r;
            } catch {
                reverted = true;
                ret = false;
            }
            // For empty _tos we expect it to revert (reverted == true). Assert that.
            assert(reverted == true);
            return;
        }

        // For non-empty _tos, the contract should attempt to call external contract at caddress for each _tos element.
        // The implementation will revert if any call returns false; however, from static observation we can only check whether C.transfer itself reverts or returns true.
        try c.transfer(from, caddress, _tos, v, _decimals) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false;
        }

        // General rule: when _tos is non-empty, C.transfer must not revert and must return true.
        assert(reverted == false && ret == true);
    }

    receive() external payable {}
}

