    // The test checks relation between transfer's revert/return and the success of the external calls.
    // We cannot observe internal per-call success directly, but we can observe whether transfer reverted
    // vs returned true. We express a conservative general rule: if transfer returns true then it did not revert;
    // and if transfer reverted then the call to the external contract must have failed at least once
    // which we approximate by observing that the call to transfer either returns true (no revert)
    // or it reverts; so we assert the mutual exclusivity and the return value meaning.

    function run(address from, address target, address[] memory tos, uint v, uint decimals) public payable {
        // Precondition: follow original contract's require
        require(tos.length > 0);

        bool didRevert;
        bool ret;
        try c.transfer(from, target, tos, v, decimals) returns (bool r) {
            didRevert = false;
            ret = r;
        } catch {
            didRevert = true;
            ret = false;
        }

        // GENERAL RULE:
        // - transfer either reverts (didRevert == true) or returns true (didRevert == false && ret == true)
        // - it must not return false without reverting (i.e., !(didRevert == false && ret == false))
        // This captures that a successful return indicates success and any failure manifests as a revert.
        assert(didRevert || ret == true);
    }

    receive() external payable {}
}

